        if a_merged and start <= a_merged[-1][1]:
            a_merged[-1][1] = max(a_merged[-1][1], end)
        else:
            a_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for cur_start, cur_end in current_ranges:
                # No overlap
                if cur_end <= b_start or cur_start >= b_end:
                    new_ranges.append([cur_start, cur_end])
                else:
                    # There is overlap, keep parts outside b
                    if cur_start < b_start:
                        new_ranges.append([cur_start, b_start])
                    if cur_end > b_end:
                        new_ranges.append([b_end, cur_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge touching intervals in result
    if not result:
        return []

    result_sorted = sorted(result)
    merged_result = []
